gold.schema_ddl:
CREATE TABLE magazzino (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    citta TEXT NOT NULL,
    stato TEXT NOT NULL CHECK (stato <> '')
);

CREATE TABLE ordine (
    id SERIAL PRIMARY KEY,
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE,
    stato TEXT NOT NULL CHECK (stato IN ('in_elaborazione', 'in_transito', 'completato', 'annullato'))
);

CREATE TABLE magazzino_ordine (
    magazzino_id INT NOT NULL REFERENCES magazzino(id),
    ordine_id INT NOT NULL REFERENCES ordine(id),
    quantita INT CHECK (quantita > 0),
    PRIMARY KEY (magazzino_id, ordine_id)
);
